// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {SimpleSuicide} from "../src/SimpleSuicide.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    SimpleSuicide c;

    function setUp() public {
        c = new SimpleSuicide();
    }

    function _run(uint256 i) internal {
        vm.assume(true);
        bool reverted;
        try c.sudicideAnyone() {
            reverted = false;
        } catch {
            reverted = true;
        }
        assertTrue(reverted || (address(c).balance == 0 && address(c) != address(0)));
    }

    function testFuzz_run(uint256 i) public {
        _run(i);
    }

    receive() external payable {}
}
